    q.fill(d_mean, 0.0f, BT).wait();
    q.fill(d_rstd, 0.0f, BT).wait();
    fused_residual_forward(k, d_residual, d_normed, d_mean, d_rstd, d_inp1,
                           d_inp2, d_weight, d_bias, B * T, C);
    q.memcpy(residual, d_residual, sizeof(float) * BTC).wait();
